#include <torch/extension.h>
#include <c10/hip/HIPStream.h>
#include <hipblas/hipblas.h>

void check_hipblas(hipblasStatus_t status, const char* operation) {
    TORCH_CHECK(status == HIPBLAS_STATUS_SUCCESS, operation, " failed with hipBLAS status ", static_cast<int>(status));
}

torch::Tensor run(const torch::Tensor& x, const torch::Tensor& y) {
    TORCH_CHECK(x.is_cuda() && y.is_cuda(), "inputs must be HIP tensors");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32 && y.scalar_type() == torch::kFloat32, "inputs must be float32");
    TORCH_CHECK(x.is_contiguous() && y.is_contiguous() && x.sizes() == y.sizes(), "inputs must be contiguous and shape-compatible");
    auto output = y.clone();
    hipblasHandle_t handle = nullptr;
    check_hipblas(hipblasCreate(&handle), "hipblasCreate");
    check_hipblas(hipblasSetStream(handle, c10::hip::getCurrentHIPStream()), "hipblasSetStream");
    const float alpha = 1.0f;
    check_hipblas(hipblasSaxpy(handle, x.numel(), &alpha, x.data_ptr<float>(), 1, output.data_ptr<float>(), 1), "hipblasSaxpy");
    check_hipblas(hipblasDestroy(handle), "hipblasDestroy");
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
    module.def("run", &run, "gfx1200 hipBLAS vector addition");
}
